-- =========================================================
-- EVENT MANAGEMENT & BOOKING SYSTEM
-- Database: PostgreSQL
-- =========================================================

-- 1. ORGANIZERS
CREATE TABLE organizers (
    organizer_id SERIAL PRIMARY KEY,
    organizer_name VARCHAR(100) NOT NULL,
    email VARCHAR(150) UNIQUE NOT NULL,
    phone VARCHAR(15) UNIQUE NOT NULL,
    organization_name VARCHAR(150),
    city VARCHAR(100),
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);


-- 2. VENUES
CREATE TABLE venues (
    venue_id SERIAL PRIMARY KEY,
    venue_name VARCHAR(150) NOT NULL,
    address VARCHAR(250) NOT NULL,
    city VARCHAR(100) NOT NULL,
    capacity INT NOT NULL CHECK (capacity > 0),
    venue_type VARCHAR(50) NOT NULL,
    contact_number VARCHAR(15),
    rental_price NUMERIC(10,2) CHECK (rental_price >= 0)
);


-- 3. EVENTS
CREATE TABLE events (
    event_id SERIAL PRIMARY KEY,
    organizer_id INT NOT NULL,
    venue_id INT NOT NULL,
    event_name VARCHAR(200) NOT NULL,
    event_category VARCHAR(50) NOT NULL,
    description TEXT,
    event_date DATE NOT NULL,
    start_time TIME NOT NULL,
    end_time TIME NOT NULL,
    ticket_price NUMERIC(10,2) DEFAULT 0 CHECK (ticket_price >= 0),
    max_attendees INT CHECK (max_attendees > 0),
    event_status VARCHAR(30) DEFAULT 'Scheduled',

    CONSTRAINT fk_event_organizer
        FOREIGN KEY (organizer_id)
        REFERENCES organizers(organizer_id),

    CONSTRAINT fk_event_venue
        FOREIGN KEY (venue_id)
        REFERENCES venues(venue_id),

    CONSTRAINT chk_event_time
        CHECK (end_time > start_time)
);


-- 4. ATTENDEES
CREATE TABLE attendees (
    attendee_id SERIAL PRIMARY KEY,
    first_name VARCHAR(50) NOT NULL,
    last_name VARCHAR(50) NOT NULL,
    email VARCHAR(150) UNIQUE NOT NULL,
    phone VARCHAR(15) UNIQUE NOT NULL,
    gender VARCHAR(20),
    date_of_birth DATE,
    city VARCHAR(100),
    registered_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);


-- 5. EVENT REGISTRATIONS
CREATE TABLE event_registrations (
    registration_id SERIAL PRIMARY KEY,
    event_id INT NOT NULL,
    attendee_id INT NOT NULL,
    registration_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    ticket_type VARCHAR(30) DEFAULT 'Regular',
    registration_status VARCHAR(30) DEFAULT 'Confirmed',

    CONSTRAINT fk_registration_event
        FOREIGN KEY (event_id)
        REFERENCES events(event_id)
        ON DELETE CASCADE,

    CONSTRAINT fk_registration_attendee
        FOREIGN KEY (attendee_id)
        REFERENCES attendees(attendee_id)
        ON DELETE CASCADE,

    CONSTRAINT unique_event_attendee
        UNIQUE (event_id, attendee_id)
);


-- 6. VENDORS
CREATE TABLE vendors (
    vendor_id SERIAL PRIMARY KEY,
    vendor_name VARCHAR(150) NOT NULL,
    vendor_type VARCHAR(50) NOT NULL,
    contact_person VARCHAR(100),
    email VARCHAR(150) UNIQUE,
    phone VARCHAR(15) UNIQUE NOT NULL,
    city VARCHAR(100),
    rating NUMERIC(3,2) CHECK (rating BETWEEN 0 AND 5)
);


-- 7. EVENT SERVICES
CREATE TABLE event_services (
    service_id SERIAL PRIMARY KEY,
    event_id INT NOT NULL,
    vendor_id INT NOT NULL,
    service_name VARCHAR(100) NOT NULL,
    service_description TEXT,
    service_cost NUMERIC(10,2) NOT NULL CHECK (service_cost >= 0),
    service_status VARCHAR(30) DEFAULT 'Booked',

    CONSTRAINT fk_service_event
        FOREIGN KEY (event_id)
        REFERENCES events(event_id)
        ON DELETE CASCADE,

    CONSTRAINT fk_service_vendor
        FOREIGN KEY (vendor_id)
        REFERENCES vendors(vendor_id)
);


-- 8. EVENT SCHEDULES
CREATE TABLE event_schedules (
    schedule_id SERIAL PRIMARY KEY,
    event_id INT NOT NULL,
    session_title VARCHAR(150) NOT NULL,
    speaker_name VARCHAR(100),
    session_date DATE NOT NULL,
    start_time TIME NOT NULL,
    end_time TIME NOT NULL,

    CONSTRAINT fk_schedule_event
        FOREIGN KEY (event_id)
        REFERENCES events(event_id)
        ON DELETE CASCADE,

    CONSTRAINT chk_schedule_time
        CHECK (end_time > start_time)
);


-- 9. PAYMENTS
CREATE TABLE payments (
    payment_id SERIAL PRIMARY KEY,
    registration_id INT NOT NULL,
    payment_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    amount NUMERIC(10,2) NOT NULL CHECK (amount > 0),
    payment_method VARCHAR(30) NOT NULL,
    payment_status VARCHAR(30) DEFAULT 'Completed',
    transaction_reference VARCHAR(100) UNIQUE,

    CONSTRAINT fk_payment_registration
        FOREIGN KEY (registration_id)
        REFERENCES event_registrations(registration_id)
        ON DELETE CASCADE
);


-- 10. FEEDBACK
CREATE TABLE feedback (
    feedback_id SERIAL PRIMARY KEY,
    event_id INT NOT NULL,
    attendee_id INT NOT NULL,
    rating INT NOT NULL CHECK (rating BETWEEN 1 AND 5),
    comments TEXT,
    feedback_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT fk_feedback_event
        FOREIGN KEY (event_id)
        REFERENCES events(event_id)
        ON DELETE CASCADE,

    CONSTRAINT fk_feedback_attendee
        FOREIGN KEY (attendee_id)
        REFERENCES attendees(attendee_id)
        ON DELETE CASCADE,

    CONSTRAINT unique_feedback
        UNIQUE (event_id, attendee_id)
);





