SELECT COUNT(*) FROM event_services;


---QUESTIONS
--1. Display all events along with organizer name
SELECT e.event_id,e.event_name,o.organizer_name
FROM events e JOIN organizers o ON e.organizer_id = o.organizer_id;

--2. Display events along with venue name and city
SELECT
    e.event_id,
    e.event_name,
    v.venue_name,
    v.city
FROM events e
JOIN venues v
    ON e.venue_id = v.venue_id;

---3. Display attendee names along with events they registered for
SELECT
    a.attendee_id,
    a.first_name,
    a.last_name,
    e.event_name
FROM attendees a
JOIN event_registrations er
    ON a.attendee_id = er.attendee_id
JOIN events e
    ON er.event_id = e.event_id;


---4. Display event name, attendee name, ticket type and registration status
SELECT
    e.event_name,
    CONCAT(a.first_name, ' ', a.last_name) AS attendee_name,
    er.ticket_type,
    er.registration_status
FROM event_registrations er
JOIN attendees a
    ON er.attendee_id = a.attendee_id
JOIN events e
    ON er.event_id = e.event_id;


---5. Display vendors who provide services for events
SELECT
    e.event_name,
    v.vendor_name,
    es.service_name
FROM event_services es
JOIN events e
    ON es.event_id = e.event_id
JOIN vendors v
    ON es.vendor_id = v.vendor_id;

---6. Display event name, vendor name, service name and service cost

SELECT
    e.event_name,
    v.vendor_name,
    es.service_name,
    es.service_cost
FROM event_services es
JOIN events e
    ON es.event_id = e.event_id
JOIN vendors v
    ON es.vendor_id = v.vendor_id;


---7. Display event schedules along with event name
SELECT
    e.event_name,
    es.session_title,
    es.speaker_name,
    es.session_date,
    es.start_time,
    es.end_time
FROM event_schedules es
JOIN events e
    ON es.event_id = e.event_id;

---8. Display payment details along with attendee and event name
SELECT
    p.payment_id,
    CONCAT(a.first_name, ' ', a.last_name) AS attendee_name,
    e.event_name,
    p.amount,
    p.payment_method,
    p.payment_status
FROM payments p
JOIN event_registrations er
    ON p.registration_id = er.registration_id
JOIN attendees a
    ON er.attendee_id = a.attendee_id
JOIN events e
    ON er.event_id = e.event_id;

---9. Find number of events organized by each organizer
SELECT
    o.organizer_name,
    COUNT(e.event_id) AS total_events
FROM organizers o
JOIN events e
    ON o.organizer_id = e.organizer_id
GROUP BY o.organizer_id, o.organizer_name;


---10. Find number of attendees registered for each event
SELECT
    e.event_name,
    COUNT(er.attendee_id) AS total_attendees
FROM events e
JOIN event_registrations er
    ON e.event_id = er.event_id
GROUP BY e.event_id, e.event_name;


--11. Find total amount collected for each event
SELECT
    e.event_name,
    SUM(p.amount) AS total_amount
FROM events e
JOIN event_registrations er
    ON e.event_id = er.event_id
JOIN payments p
    ON er.registration_id = p.registration_id
GROUP BY e.event_id, e.event_name;


--12. Find total service cost for each event

SELECT
    e.event_name,
    SUM(es.service_cost) AS total_service_cost
FROM events e
JOIN event_services es
    ON e.event_id = es.event_id
GROUP BY e.event_id, e.event_name;


---13. Find number of vendors in each city

SELECT
    city,
    COUNT(vendor_id) AS total_vendors
FROM vendors
GROUP BY city
ORDER BY total_vendors DESC;

---14. Find average vendor rating in each city
SELECT
    city,
    ROUND(AVG(rating), 2) AS average_rating
FROM vendors
GROUP BY city
ORDER BY average_rating DESC;

--15. Find number of attendees from each city
SELECT
    city,
    COUNT(attendee_id) AS total_attendees
FROM attendees
GROUP BY city
ORDER BY total_attendees DESC;

---16. Find number of registrations for each ticket type
SELECT
    ticket_type,
    COUNT(registration_id) AS total_registrations
FROM event_registrations
GROUP BY ticket_type
ORDER BY total_registrations DESC;



---17. Display organizers who organized more than 5 events
SELECT
    o.organizer_name,
    COUNT(e.event_id) AS total_events
FROM organizers o
JOIN events e
    ON o.organizer_id = e.organizer_id
GROUP BY o.organizer_id, o.organizer_name
HAVING COUNT(e.event_id) > 5;


--18. Display events having more than 10 registered attendees
SELECT
    e.event_name,
    COUNT(er.attendee_id) AS total_attendees
FROM events e
JOIN event_registrations er
    ON e.event_id = er.event_id
GROUP BY e.event_id, e.event_name
HAVING COUNT(er.attendee_id) > 10;



---19. Display cities having more than 20 attendees

SELECT
    city,
    COUNT(attendee_id) AS total_attendees
FROM attendees
GROUP BY city
HAVING COUNT(attendee_id) > 20;

---20. Display vendors whose average rating is greater than 4
SELECT
    city,
    ROUND(AVG(rating), 2) AS average_rating
FROM vendors
GROUP BY city
HAVING AVG(rating) > 4;

---21. Display events where total service cost is greater than 50,000

SELECT
    e.event_name,
    SUM(es.service_cost) AS total_service_cost
FROM events e
JOIN event_services es
    ON e.event_id = es.event_id
GROUP BY e.event_id, e.event_name
HAVING SUM(es.service_cost) > 50000;

---22. Display ticket types having more than 50 registrations

SELECT
    ticket_type,
    COUNT(registration_id) AS total_registrations
FROM event_registrations
GROUP BY ticket_type
HAVING COUNT(registration_id) > 50;


---23. Find the organizer who organized the highest number of events
SELECT
    o.organizer_name,
    COUNT(e.event_id) AS total_events
FROM organizers o
JOIN events e
    ON o.organizer_id = e.organizer_id
GROUP BY o.organizer_id, o.organizer_name
ORDER BY total_events DESC
LIMIT 1;


---24. Find the event with the highest number of registered attendees
SELECT
    e.event_name,
    COUNT(er.attendee_id) AS total_attendees
FROM events e
JOIN event_registrations er
    ON e.event_id = er.event_id
GROUP BY e.event_id, e.event_name
ORDER BY total_attendees DESC
LIMIT 1;

---25. Find each organizer's total revenue
SELECT
    o.organizer_name,
    SUM(p.amount) AS total_revenue
FROM organizers o
JOIN events e
    ON o.organizer_id = e.organizer_id
JOIN event_registrations er
    ON e.event_id = er.event_id
JOIN payments p
    ON er.registration_id = p.registration_id
GROUP BY o.organizer_id, o.organizer_name
ORDER BY total_revenue DESC;

---26. Find total payment collected through each payment method
SELECT
    payment_method,
    COUNT(payment_id) AS total_transactions,
    SUM(amount) AS total_amount
FROM payments
GROUP BY payment_method
ORDER BY total_amount DESC;

----27. Find events whose average feedback rating is greater than 4
SELECT
    e.event_name,
    ROUND(AVG(f.rating), 2) AS average_rating
FROM events e
JOIN feedback f
    ON e.event_id = f.event_id
GROUP BY e.event_id, e.event_name
HAVING AVG(f.rating) > 4;


---28. Find vendors who provided services for more than 5 even
SELECT
    v.vendor_name,
    COUNT(DISTINCT es.event_id) AS total_events
FROM vendors v
JOIN event_services es
    ON v.vendor_id = es.vendor_id
GROUP BY v.vendor_id, v.vendor_name
HAVING COUNT(DISTINCT es.event_id) > 5;


----29. Find the event that generated the highest total payment
SELECT
    e.event_name,
    SUM(p.amount) AS total_payment
FROM events e
JOIN event_registrations er
    ON e.event_id = er.event_id
JOIN payments p
    ON er.registration_id = p.registration_id
GROUP BY e.event_id, e.event_name
ORDER BY total_payment DESC
LIMIT 1;









